    public EdgeApplication testCreate() throws Throwable {
    EdgeApplication entity = null;

    LOGGER.info( "EdgeApplicationTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a EdgeApplication");

    StringBuilder msg = new StringBuilder( "-- Failed to create a EdgeApplication" );

    try {
        entity = service.createEdgeApplication( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getEdgeApplicationId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a EdgeApplication with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

