    /**
     * Tests getting all EdgeApplications.
     *
     * @return    Collection
     */
    public List<EdgeApplication> testGetAll() throws Throwable {
    LOGGER.info( "EdgeApplicationTest:testGetAll() - Retrieving Collection of EdgeApplications:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all EdgeApplication : " );
    List<EdgeApplication> collection  = null;

    try {
        // call the static get method on the EdgeApplicationService
        collection = service.getAllEdgeApplication();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            EdgeApplication currEntity  = null;
            Iterator<EdgeApplication> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getEdgeApplicationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

